/**
 * Connects JH149 durable idempotency/result verification to the existing
 * Secure56 Android workflow generated by durable-mcp-workflow-patch.mjs.
 *
 * This patch does not bypass Android approvals and does not trust a client
 * supplied `signatureVerified` flag. The server marks screen evidence as
 * signature verified only after the existing Secure56 completion MAC,
 * workflow echo, action digest and trusted-device binding have passed.
 */
const importBlock = "import {createJHResultVerificationGuard,runProtectedJHAction,reconcileProtectedJHAction,EffectKind,EvidenceSource,createEvidence} from '../deployment/jh-result-verification/index.mjs';\n";

const sharedBlock = String.raw`let jhResultVerificationGuardV1Promise=null;
function jhResultVerificationGuard56(){
  if(!jhResultVerificationGuardV1Promise){
    const configured=(process.env.JH_WORKFLOW_STATE_DIR||'').trim();
    jhResultVerificationGuardV1Promise=createJHResultVerificationGuard({
      stateDirectory:configured||undefined,
      filename:'jh-result-execution-guard-v1.json',
      forceRecovery:true,
      requireSignature:true
    });
  }
  return jhResultVerificationGuardV1Promise;
}
`;

const helperBlock = String.raw`
  function jhRequireResultWorkflow56(w){
    jhRequireWorkflow56(w);
    if(w.phase==='ABORTED_BY_TERMINATION')throw Error('workflow_aborted_by_termination_no_replay');
    jhRequireCommand56(w.device,w.id);
    if(!w.processEpochAtStart||devices.get(w.device)?.processEpoch!==w.processEpochAtStart)throw Error('workflow_process_epoch_changed_no_replay');
  }

  function jhResultVerificationSummary56(result){
    if(!result||typeof result!=='object')return null;
    return {status:result.status||null,verified:result.verified===true,
      effectConfirmed:result.effectConfirmed===true,duplicate:result.duplicate===true,
      executed:result.executed===true,state:result.record?.state||null,
      executionId:result.record?.executionId||null,reason:result.reason||null};
  }
  function jhSnapshotEvidenceFromJob56(w,stepId,expectedPackage,record){
    jhRequireResultWorkflow56(w);
    const log=w.jobs.find(x=>x.stepId===stepId);
    if(!log||log.runtimeDigest!==jhWorkflowRuntimeDigest56)return null;
    const j=jobs.get(log.jobId);
    if(!j||j.status!=='complete'||j.result?.ok!==true)return null;
    const echoed=j.result?.jhMcpWorkflow;
    if(!echoed||echoed.workflowId!==w.id||echoed.workflowStepId!==stepId||
       echoed.workflowPlanDigest!==w.plan||echoed.workflowActionDigest!==j.workflowActionDigest||
       echoed.jobId!==j.id)return null;
    let rows;
    try{rows=JSON.parse(j.result.url);if(!Array.isArray(rows))return null;}catch{return null;}
    const packages=[...new Set(rows.map(x=>x?.package).filter(jhAndroidPackageName56))];
    if(packages.length!==1||packages[0]!==expectedPackage)return null;
    const capturedAt=typeof j.completedAt==='string'&&Number.isFinite(Date.parse(j.completedAt))
      ?j.completedAt:new Date().toISOString();
    return createEvidence({record,source:EvidenceSource.SCREEN_READBACK,capturedAt,
      signatureVerified:true,extraBinding:{deviceDigest:w.secureDeviceDigest},
      facts:{screen:{foregroundPackage:packages[0],expectedPackage,workflowId:w.id,
        snapshotStepId:stepId,secureWorkflowEchoVerified:true}}});
  }
  async function jhRunProtectedUiAction56(w,{intentId,action,payload,dispatchStepId,snapshotStepId,expectedPackage}){
    jhRequireResultWorkflow56(w);
    const holder=await jhResultVerificationGuard56();
    jhRequireResultWorkflow56(w);
    return runProtectedJHAction({guard:holder.guard,workflowId:w.id,stepId:intentId,
      action,payload,expectedFacts:[{source:EvidenceSource.SCREEN_READBACK,
        path:'screen.foregroundPackage',op:'eq',value:expectedPackage}],
      effect:{kind:EffectKind.UI_STATE,requireScreenReadback:true},
      metadata:{deviceDigest:w.secureDeviceDigest,planDigest:w.plan,
        trustedSecureBridgeVersion:56},
      dispatchAction:async context=>{
        jhRequireResultWorkflow56(w);
        await jhWorkflowStep56(w,dispatchStepId,'open_url',payload);
        return {accepted:true,workflowId:w.id,stepId:dispatchStepId,
          executionId:context.executionId,invocationOnly:true};
      },
      readbackAction:async({record})=>{
        jhRequireResultWorkflow56(w);
        await jhScreenSettle56();
        const foregroundPackage=await jhWorkflowStep56(w,snapshotStepId,'agent_snapshot',{},expectedPackage);
        jhRequireResultWorkflow56(w);
        return [createEvidence({record,source:EvidenceSource.SCREEN_READBACK,
          signatureVerified:true,extraBinding:{deviceDigest:w.secureDeviceDigest},
          facts:{screen:{foregroundPackage,expectedPackage,workflowId:w.id,
            snapshotStepId,secureWorkflowEchoVerified:true}}})];
      },
      reconcileAction:async({record})=>{
        const evidence=jhSnapshotEvidenceFromJob56(w,snapshotStepId,expectedPackage,record);
        return evidence?[evidence]:[];
      },
      resultProjector:({verification})=>({foregroundPackage:expectedPackage,
        effectReference:verification?.effectReference||null})});
  }
  async function jhReconcileProtectedUiAction56(w,{intentId,action,payload,snapshotStepId,expectedPackage}){
    jhRequireResultWorkflow56(w);
    const holder=await jhResultVerificationGuard56();
    jhRequireResultWorkflow56(w);
    return reconcileProtectedJHAction({guard:holder.guard,workflowId:w.id,stepId:intentId,
      action,payload,expectedFacts:[{source:EvidenceSource.SCREEN_READBACK,
        path:'screen.foregroundPackage',op:'eq',value:expectedPackage}],
      effect:{kind:EffectKind.UI_STATE,requireScreenReadback:true},
      reconcileAction:async({record})=>{
        const evidence=jhSnapshotEvidenceFromJob56(w,snapshotStepId,expectedPackage,record);
        return evidence?[evidence]:[];
      },
      resultProjector:({verification})=>({foregroundPackage:expectedPackage,
        effectReference:verification?.effectReference||null})});
  }
  async function jhReconcileVerifiedWorkflow56(w){
    if(w.phase!=='NEEDS_REVIEW')return {reconciled:false,resultVerification:null};
    let spec=null;
    if(w.initialPackage&&w.jobs.some(x=>x.stepId==='step_4'))spec={intentId:'RETURN_PREVIOUS_EFFECT',
      action:'RETURN_PREVIOUS',payload:{target:'previous_work_app',url:''},snapshotStepId:'step_4',
      expectedPackage:w.initialPackage,targetPhase:'VERIFIED'};
    else if(w.jobs.some(x=>x.stepId==='step_2'))spec={intentId:'OPEN_KAKAO_T_EFFECT',
      action:'OPEN_KAKAO_T',payload:{target:'카카오T',url:'카카오T'},snapshotStepId:'step_2',
      expectedPackage:'com.kakao.taxi',targetPhase:'OPENED'};
    if(!spec)return {reconciled:false,resultVerification:null};
    const result=await jhReconcileProtectedUiAction56(w,spec);
    const summary=jhResultVerificationSummary56(result);
    if(result?.verified!==true)return {reconciled:false,resultVerification:summary};
    if(!jhValidateLateSnapshot56(w,spec.snapshotStepId,spec.expectedPackage))
      return {reconciled:false,resultVerification:summary};
    jhRequireResultWorkflow56(w);w.phase=spec.targetPhase;jhPersistWorkflows56();
    return {reconciled:true,resultVerification:summary};
  }
`;

const oldStatus = String.raw`    if(mode==='STATUS'){
      const reconciled=jhReconcileLateWorkflow56(w);
      return textResult({ok:true,reconciled,...jhWorkflowView56(w)});
    }`;
const newStatus = String.raw`    if(mode==='STATUS'){
      const reconciliation=await jhReconcileVerifiedWorkflow56(w);
      return textResult({ok:true,reconciled:reconciliation.reconciled,
        resultVerification:reconciliation.resultVerification,...jhWorkflowView56(w)});
    }`;

const oldExecution = String.raw`    w.phase='RUNNING';jhPersistWorkflows56();
    try{
      if(mode==='OPEN_KAKAO_T'){
        await jhWorkflowStep56(w,'step_1','open_url',{target:'카카오T',url:'카카오T'});
        await jhScreenSettle56();
        await jhWorkflowStep56(w,'step_2','agent_snapshot',{},'com.kakao.taxi');
        jhRequireWorkflow56(w);w.phase='OPENED';jhPersistWorkflows56();
      }else{
        await jhWorkflowStep56(w,'step_3','open_url',{target:'previous_work_app',url:''});
        await jhScreenSettle56();
        await jhWorkflowStep56(w,'step_4','agent_snapshot',{},w.initialPackage);
        jhRequireWorkflow56(w);w.phase='VERIFIED';jhPersistWorkflows56();
      }
      return textResult({ok:true,...jhWorkflowView56(w)});
    }catch(e){if(jhMcpWorkflows56.get(w.id)!==w)return textResult({ok:false,code:'site_switch_discarded'});w.phase='NEEDS_REVIEW';jhPersistWorkflows56();return textResult({ok:false,code:String(e?.message||'workflow_step_unconfirmed'),...jhWorkflowView56(w)});}`;

const newExecution = String.raw`    let resultVerification=null;
    w.phase='RUNNING';jhPersistWorkflows56();
    try{
      if(mode==='OPEN_KAKAO_T'){
        const result=await jhRunProtectedUiAction56(w,{intentId:'OPEN_KAKAO_T_EFFECT',
          action:'OPEN_KAKAO_T',payload:{target:'카카오T',url:'카카오T'},
          dispatchStepId:'step_1',snapshotStepId:'step_2',expectedPackage:'com.kakao.taxi'});
        resultVerification=jhResultVerificationSummary56(result);
        if(result?.verified!==true)throw Error('result_verification_not_confirmed:'+String(result?.status||'unknown'));
        jhRequireResultWorkflow56(w);w.phase='OPENED';jhPersistWorkflows56();
      }else{
        const result=await jhRunProtectedUiAction56(w,{intentId:'RETURN_PREVIOUS_EFFECT',
          action:'RETURN_PREVIOUS',payload:{target:'previous_work_app',url:''},
          dispatchStepId:'step_3',snapshotStepId:'step_4',expectedPackage:w.initialPackage});
        resultVerification=jhResultVerificationSummary56(result);
        if(result?.verified!==true)throw Error('result_verification_not_confirmed:'+String(result?.status||'unknown'));
        jhRequireResultWorkflow56(w);w.phase='VERIFIED';jhPersistWorkflows56();
      }
      return textResult({ok:true,resultVerification,...jhWorkflowView56(w)});
    }catch(e){if(jhMcpWorkflows56.get(w.id)!==w)return textResult({ok:false,code:'site_switch_discarded'});if(w.phase==='ABORTED_BY_TERMINATION')return textResult({ok:false,code:'workflow_aborted_by_termination_no_replay',...jhWorkflowView56(w)});w.phase='NEEDS_REVIEW';jhPersistWorkflows56();return textResult({ok:false,
      code:String(e?.message||'workflow_step_unconfirmed'),resultVerification,...jhWorkflowView56(w)});}`;

export function patchResultVerificationRuntime(source) {
  if (typeof source !== 'string') throw Error('result_verification_source_required');
  const scope = 'function createMcp(){';
  const toolAnchor = "  registerOAuthTool('life_android_workflow_link',{ ".trimEnd();
  const exactToolAnchor = "  registerOAuthTool('life_android_workflow_link',{";
  if (source.includes('jhResultVerificationGuardV1Promise') || source.includes(importBlock)) {
    throw Error('result_verification_runtime_already_patched');
  }
  if (source.split(scope).length !== 2 || source.split(exactToolAnchor).length !== 2 ||
      source.split(oldStatus).length !== 2 || source.split(oldExecution).length !== 2) {
    throw Error('result_verification_runtime_anchor_changed');
  }
  let output = importBlock + source.replace(scope, sharedBlock + scope);
  output = output.replace(exactToolAnchor, helperBlock + exactToolAnchor);
  output = output.replace(oldStatus, newStatus).replace(oldExecution, newExecution);

  let restored = output.slice(importBlock.length)
    .replace(sharedBlock + scope, scope)
    .replace(helperBlock + exactToolAnchor, exactToolAnchor)
    .replace(newStatus, oldStatus)
    .replace(newExecution, oldExecution);
  if (restored !== source) throw Error('result_verification_patch_scope_changed');
  return output;
}
